import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Introduction","description":"Wake is a project tracker your coding agents use: what it does, how plans, claims and evidence work, and where to start.","frontmatter":{"prev":false,"description":"Wake is a project tracker your coding agents use: what it does, how plans, claims and evidence work, and where to start."},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794486787000}'),n={name:"index.md"};function r(i,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Wake is a project tracker your coding agents use. The plan lives in your repository, written with OpenSpec, Spec Kit or ODD; Wake shows which agent session works on which task, how far it got and the proof that it was done. It runs on a server you own.</p><p>The free plan has no time limit: up to 3 people in all, however many installations you run, with unlimited agents, projects and tasks.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>You plan in your repository, and <code>wake sync</code> sends the plan to Wake.</li><li>An agent claims a task before it starts, so two sessions never build the same thing.</li><li>It reports its progress and attaches evidence: proof such as test output or screenshots. A task is done only with that evidence, or with a stated reason why none is possible.</li></ol><p>Claude Code, OpenCode, Pi and Codex connect with one command, <code>wake setup</code>. The words above (claim, session, evidence and the rest) are explained in <a href="/wake-dist/docs/start/concepts">Concepts</a>.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="/wake-dist/docs/start/install">Install Wake</a>: the server, with one command.</li><li><a href="/wake-dist/docs/start/cli">Install the CLI and sign in</a>: the <code>wake</code> program your agents run.</li><li><a href="/wake-dist/docs/start/first-project">Your first project</a>: create your account and connect a repository.</li></ol><h2 id="the-sections" tabindex="-1">The sections <a class="header-anchor" href="#the-sections" aria-label="Permalink to &quot;The sections&quot;">​</a></h2><ul><li><a href="/wake-dist/docs/agents/">Agents and plans</a>: connect Claude Code, OpenCode, Pi or Codex, and plan with OpenSpec, Spec Kit or ODD.</li><li><a href="/wake-dist/docs/use/">Use Wake</a>: track tasks, roadmaps, versions and the people in your workspace.</li><li><a href="/wake-dist/docs/run/">Run your server</a>: upgrade, back up, configure sign-in and keep your installation healthy.</li><li><a href="/wake-dist/docs/reference/">Reference</a>: every command, setting and error, and the license.</li></ul>',10)])])}const w=a(n,[["render",r]]);export{u as __pageData,w as default};
